def count_seconds_to_move_girls_in_front(s):
    if 'M' not in s or 'F' not in s:
        return 0

    seconds = 0
    while True:
        changed = False
        for i in range(len(s) - 1):
            if s[i] == 'M' and s[i + 1] == 'F':
                s = s[:i] + 'F' + 'M' + s[i + 2:]
                seconds += 1
                changed = True
                break
        if not changed:
            break
    return seconds

# Read input from stdin
s = input().strip()

